custom_fields.contenu:
[[[
  const weather = states['weather.forecast_maison'];
  const forecastSensor = states['sensor.previsions_meteo_maison'];

  const temperature =
    weather?.attributes?.temperature ?? '--';

  const condition =
    weather?.state ?? 'partlycloudy';

  const forecasts =
    forecastSensor?.attributes?.forecast ?? [];

  const icons = {
    'clear-night': '🌙',
    sunny: '☀️',
    partlycloudy: '🌤️',
    cloudy: '☁️',
    rainy: '🌧️',
    pouring: '🌧️',
    lightning: '⛈️',
    'lightning-rainy': '⛈️',
    snowy: '🌨️',
    'snowy-rainy': '🌨️',
    fog: '🌫️',
    windy: '💨',
    'windy-variant': '💨',
    hail: '🌨️',
    exceptional: '⚠️'
  };

  const descriptions = {
    'clear-night': 'Nuit dégagée',
    sunny: 'Ensoleillé',
    partlycloudy: 'Partiellement nuageux',
    cloudy: 'Nuageux',
    rainy: 'Pluvieux',
    pouring: 'Fortes pluies',
    lightning: 'Orageux',
    'lightning-rainy': 'Orage et pluie',
    snowy: 'Neige',
    'snowy-rainy': 'Neige et pluie',
    fog: 'Brouillard',
    windy: 'Venteux',
    'windy-variant': 'Venteux',
    hail: 'Grêle',
    exceptional: 'Conditions exceptionnelles'
  };

  const labels = [
    'AUJ.',
    'DEM.',
    'J+2',
    'J+3',
    'J+4'
  ];

  const formatTemp = (value) => {
    if (value === undefined || value === null) return '--';

    const n = Number(value);

    if (Number.isNaN(n)) return '--';

    return Number.isInteger(n)
      ? n.toString()
      : n.toFixed(1).replace('.', ',');
  };

  const forecastHtml =
    Array.from({ length: 5 }, (_, index) => {

      const item = forecasts[index];

      if (!item) {
        return `
          <div class="jour">
            <div class="label">${labels[index]}</div>
            <div class="forecast-icon">🌤️</div>
            <div class="max">--°</div>
            <div class="min">--°</div>
          </div>
        `;
      }

      const itemCondition =
        item.condition ?? 'partlycloudy';

      return `
        <div class="jour">

          <div class="label">
            ${labels[index]}
          </div>

          <div class="forecast-icon">
            ${icons[itemCondition] ?? '🌤️'}
          </div>

          <div class="max">
            ${formatTemp(item.temperature)}°
          </div>

          <div class="min">
            ${formatTemp(item.templow)}°
          </div>

        </div>
      `;
    }).join('');

  return `
    <div class="meteo-v7">

      <div class="haut">

        <div class="icone-principale">
          ${icons[condition] ?? '🌤️'}
        </div>

        <div class="infos">

          <div class="titre">
            Météo Maison Blaise
          </div>

          <div class="temperature">
            ${formatTemp(temperature)}°C
          </div>

          <div class="condition">
            ${descriptions[condition] ?? condition}
          </div>

        </div>

      </div>

      <div class="separateur"></div>

      <div class="previsions">
        ${forecastHtml}
      </div>

    </div>
  `;
]]]

extra_styles:
.meteo-v7 {
  width: 100%;
  height: 100%;

  box-sizing: border-box;

  padding: 24px 28px 20px;

  display: flex;
  flex-direction: column;

  color: white;

  text-align: left;
}

.haut {
  display: flex;
  align-items: center;

  min-height: 118px;
}

.icone-principale {
  width: 120px;

  flex: 0 0 120px;

  display: flex;
  align-items: center;
  justify-content: center;

  font-size: 72px;

  line-height: 1;

  filter:
    drop-shadow(
      0 0 10px rgba(255, 190, 40, 0.30)
    );
}

.infos {
  min-width: 0;

  padding-left: 10px;
}

.titre {
  margin-bottom: 4px;

  color:
    rgba(235, 242, 248, 0.82);

  font-size:
    clamp(12px, 0.9vw, 15px);

  white-space: nowrap;
}

.temperature {
  color: #ffffff;

  font-size:
    clamp(34px, 3vw, 48px);

  font-weight: 600;

  line-height: 1;

  white-space: nowrap;
}

.condition {
  margin-top: 7px;

  color:
    rgba(180, 200, 218, 0.72);

  font-size:
    clamp(11px, 0.8vw, 14px);
}

.separateur {
  width: 100%;
  height: 1px;

  background:
    rgba(255, 255, 255, 0.07);

  margin:
    4px 0 14px;
}

.previsions {
  flex: 1;

  display: grid;

  grid-template-columns:
    repeat(5, 1fr);

  align-items: center;
}

.jour {
  min-width: 0;

  display: flex;
  flex-direction: column;

  align-items: center;

  gap: 4px;

  text-align: center;
}

.label {
  color:
    rgba(190, 205, 218, 0.75);

  font-size:
    clamp(8px, 0.62vw, 11px);

  font-weight: 500;
}

.forecast-icon {
  margin-top: 3px;

  font-size:
    clamp(23px, 1.8vw, 31px);

  line-height: 1.15;
}

.max {
  color:
    rgba(245, 248, 252, 0.96);

  font-size:
    clamp(11px, 0.8vw, 14px);

  font-weight: 700;
}

.min {
  color:
    rgba(160, 180, 198, 0.72);

  font-size:
    clamp(9px, 0.65vw, 11px);
}

@media (max-width: 1100px) {

  .meteo-v7 {
    padding-left: 18px;
    padding-right: 18px;
  }

  .icone-principale {
    width: 90px;
    flex-basis: 90px;

    font-size: 58px;
  }

}
